const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry Definitions
  const cumbreVieja = ee.Geometry.Point([-17.83, 28.57]); // Cumbre Vieja volcano
  const funchal = ee.Geometry.Point([-16.91, 32.65]); // Funchal, Madeira Island

  // Buffer areas around points for regional analysis
  const cumbreViejaArea = cumbreVieja.buffer(50000); // 50km buffer
  const funchalArea = funchal.buffer(50000); // 50km buffer

  // 2. Data Acquisition - TROPOMI SO2 data
  const date = '2021-10-18';
  const so2Collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_SO2')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .select('SO2_column_number_density');

  // Check if collection has data
  const collectionSize = so2Collection.size().getInfo();
  console.log(`SO2 Images on ${date}: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get the single image for that day
  const so2Image = so2Collection.first();

  // 3. Processing - Calculate mean SO2 for each location
  const cumbreStats = so2Image.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: cumbreViejaArea,
    scale: 1000,
    maxPixels: 1e9
  });

  const funchalStats = so2Image.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: funchalArea,
    scale: 1000,
    maxPixels: 1e9
  });

  const cumbreMean = cumbreStats.get('SO2_column_number_density_mean').getInfo();
  const cumbreCount = cumbreStats.get('SO2_column_number_density_count').getInfo();
  const funchalMean = funchalStats.get('SO2_column_number_density_mean').getInfo();
  const funchalCount = funchalStats.get('SO2_column_number_density_count').getInfo();

  console.log(`Cumbre Vieja - SO2: ${cumbreMean?.toFixed(6)}, Pixels: ${cumbreCount}`);
  console.log(`Funchal - SO2: ${funthalMean?.toFixed(6)}, Pixels: ${funthalCount}`);

  // 4. Validation & Final Answer
  if (cumbreCount === 0 || funchalCount === 0) {
    console.log("<answer>C2</answer>");
  } else if (cumbreMean === null || funchalMean === null || 
             isNaN(cumbreMean) || isNaN(funthalMean)) {
    console.log("<answer>C3</answer>");
  } else if (cumbreMean > funchalMean) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
